// MEL-AUDIT-04: the weekly architecture audit runs in GitHub Actions
// (scripts/architecture-audit.mjs reads the whole repository, too heavy for a
// Worker) and posts its report here with a GitHub OIDC identity. The weekly
// domain audit turns the latest report into findings.
import { authorizeGitHubActionsOidcRequest } from '../security/github-actions-oidc.js';

const WORKFLOW = 'architecture-audit.yml';
const KEY = 'latest';
const DAY_MS = 86_400_000;

const json = (body, status = 200) => new Response(JSON.stringify(body), { status, headers: { 'content-type': 'application/json; charset=utf-8' } });

async function ensureSchema(db) {
  await db.prepare('CREATE TABLE IF NOT EXISTS mel_architecture_audit (id TEXT PRIMARY KEY, report_json TEXT NOT NULL, source_sha TEXT, received_at INTEGER NOT NULL)').run();
}

const list = (value, max) => (Array.isArray(value) ? value.slice(0, max) : []);

export async function storeArchitectureReport(db, report, { sha = '', now = Date.now() } = {}) {
  if (report?.schema !== 'mel.architecture-audit/v1') throw Object.assign(new Error('ARCHITECTURE_REPORT_SCHEMA_INVALID'), { status: 400 });
  // MEL-AUDIT-04: a report is bound to the exact signed commit; without a
  // valid 40-hex identity it is refused, and a replay of the same commit is
  // recorded once (no refreshed date, no extra finding).
  const sourceSha = String(sha || '').toLowerCase();
  if (!/^[0-9a-f]{40}$/.test(sourceSha)) throw Object.assign(new Error('ARCHITECTURE_REPORT_IDENTITY_INVALID'), { status: 401 });
  await ensureSchema(db);
  const existing = await db.prepare('SELECT source_sha FROM mel_architecture_audit WHERE id = ?').bind(KEY).first().catch(() => null);
  if (existing?.source_sha === sourceSha) return { ok: true, status: 'ARCHITECTURE_REPORT_ALREADY_STORED' };
  // Bounded copy: a report never grows D1 beyond a few kilobytes.
  const bounded = {
    schema: report.schema,
    source_files: Number(report.source_files) || 0,
    max_lines: Number(report.max_lines) || 1500,
    oversized: list(report.oversized, 20),
    untested_modules: list(report.untested_modules, 200),
    legacy_imported: list(report.legacy_imported, 50),
    duplicate_exports: list(report.duplicate_exports, 50),
    ...(Array.isArray(report.new_models) ? { new_models: list(report.new_models, 30).map(String) } : {}),
    ...(report.ui?.schema === 'mel.ui-production-audit/v1' ? { ui: {
      schema: report.ui.schema,
      pages: Number(report.ui.pages) || 0,
      api_calls: Number(report.ui.api_calls) || 0,
      blocked_calls: Number(report.ui.blocked_calls) || 0,
      findings: list(report.ui.findings, 40).map(row => ({ code: String(row?.code || '').slice(0, 60), detail: String(row?.detail || '').slice(0, 300) })),
    } } : {}),
  };
  await db.prepare(`INSERT INTO mel_architecture_audit (id, report_json, source_sha, received_at) VALUES (?, ?, ?, ?)
    ON CONFLICT(id) DO UPDATE SET report_json = excluded.report_json, source_sha = excluded.source_sha, received_at = excluded.received_at`)
    .bind(KEY, JSON.stringify(bounded), sourceSha, now).run();
  return { ok: true, status: 'ARCHITECTURE_REPORT_STORED' };
}

export async function readArchitectureReport(db) {
  try {
    const row = await db.prepare('SELECT report_json, source_sha, received_at FROM mel_architecture_audit WHERE id = ?').bind(KEY).first();
    return row ? { report: JSON.parse(row.report_json), source_sha: row.source_sha, received_at: Number(row.received_at) } : null;
  } catch { return null; }
}

/** Findings from the latest report; a report older than 8 days is itself a finding. */
export function architectureFindings(latest, { now = Date.now() } = {}) {
  if (!latest) return [];
  const findings = [];
  if (now - latest.received_at > 8 * DAY_MS) {
    findings.push({ code: 'ARCHITECTURE_AUDIT_STALE', detail: 'dernier rapport d’architecture il y a ' + Math.round((now - latest.received_at) / DAY_MS) + ' jours' });
    return findings;
  }
  const r = latest.report || {};
  for (const row of r.oversized || []) findings.push({ code: 'ARCH_FILE_TOO_LARGE', detail: row.path + ' : ' + row.lines + ' lignes (max ' + r.max_lines + ')' });
  for (const row of r.legacy_imported || []) findings.push({ code: 'ARCH_LEGACY_STILL_IMPORTED', detail: row.path + ' importé par ' + row.imported_by });
  for (const row of r.duplicate_exports || []) findings.push({ code: 'ARCH_DUPLICATE_EXPORT', detail: row.name + ' exporté par ' + (row.files || []).join(', ') });
  // MEL-AUDIT-06: each free model MEL does not use yet is a discovery to
  // measure through the MAX chain before any registry change.
  for (const model of (r.new_models || []).slice(0, 10)) findings.push({ code: 'UPGRADE_MODEL_AVAILABLE', detail: model + ' disponible sur Workers AI, absent de ModelRegistry : à mesurer (sonde code, coût) avant adoption' });
  // MEL-UI-AUDIT: what the owner would see broken on the real pages.
  for (const row of (r.ui?.findings || []).filter(row => /^UI_/.test(row.code))) findings.push(row);
  const untested = r.untested_modules || [];
  if (untested.length) findings.push({ code: 'ARCH_UNTESTED_MODULES', detail: untested.length + ' modules src/ sans test qui les importe, dont ' + untested.slice(0, 5).join(', ') });
  return findings;
}

export async function maybeHandleArchitectureAuditInternal(request, env = {}) {
  const url = new URL(request.url);
  if (url.pathname !== '/api/internal/architecture-audit') return null;
  if (request.method !== 'POST') return json({ ok: false, code: 'METHOD_NOT_ALLOWED' }, 405);
  const auth = await authorizeGitHubActionsOidcRequest(request, env, {
    allowedWorkflows: [WORKFLOW],
    allowedWorkflowBranches: ['main'],
    allowedEvents: ['schedule', 'workflow_dispatch'],
  });
  if (!auth.ok) return json({ ok: false, code: auth.code }, auth.status || 401);
  const body = await request.json().catch(() => null);
  try {
    return json(await storeArchitectureReport(env.DB, body, { sha: auth.identity?.sha }));
  } catch (error) {
    return json({ ok: false, code: String(error?.message || 'ARCHITECTURE_REPORT_FAILED') }, Number(error?.status) || 503);
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, mkdir, writeFile, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { auditArchitecture } from '../scripts/architecture-audit.mjs';
import { architectureFindings, readArchitectureReport, storeArchitectureReport } from '../src/diagnostics/architecture-audit-store.js';
import { sqliteD1 } from './helpers/sqlite-d1.mjs';

test('the repository audit finds oversized, untested, legacy-imported and duplicated code', async t => {
  const root = await mkdtemp(path.join(tmpdir(), 'mel-arch-'));
  t.after(() => rm(root, { recursive: true, force: true }));
  await mkdir(path.join(root, 'src'), { recursive: true });
  await mkdir(path.join(root, 'tests'), { recursive: true });
  await writeFile(path.join(root, 'src/big.js'), 'export function same() {}\n'.repeat(1600));
  await writeFile(path.join(root, 'src/old.js'), '// LEGACY_DO_NOT_USE\nexport function same() {}\n');
  await writeFile(path.join(root, 'src/roadmap.js'), "export function item(){ return 'LEGACY_DO_NOT_USE'; }\n");
  await writeFile(path.join(root, 'src/user.js'), "import { same } from './old.js';\nimport { item } from './roadmap.js';\nexport function onRequestGet() {}\n");
  await writeFile(path.join(root, 'src/page.js'), 'export function onRequestGet() {}\n');
  await writeFile(path.join(root, 'tests/user.test.mjs'), "import '../src/user.js';\n");
  const report = await auditArchitecture(root);
  assert.deepEqual(report.oversized.map(r => r.path), ['src/big.js']);
  assert.deepEqual(report.untested_modules, ['src/big.js', 'src/old.js', 'src/page.js', 'src/roadmap.js']);
  assert.deepEqual(report.legacy_imported, [{ path: 'src/old.js', imported_by: 'src/user.js' }]);
  assert.deepEqual(report.duplicate_exports.map(d => d.name), ['same'], 'onRequest* page handlers are not duplicates');
});

test('MEL stores the report and the weekly audit turns it into findings', async () => {
  const db = sqliteD1();
  const now = Date.parse('2026-10-26T05:00:00Z');
  await assert.rejects(storeArchitectureReport(db, { schema: 'other' }), /SCHEMA_INVALID/);
  await storeArchitectureReport(db, {
    schema: 'mel.architecture-audit/v1', max_lines: 1500,
    oversized: [{ path: 'src/api/native-chat.js', lines: 3020 }],
    untested_modules: ['src/a.js'], legacy_imported: [], duplicate_exports: [{ name: 'x', files: ['src/a.js', 'src/b.js'] }],
  }, { sha: 'ab01ab01ab01ab01ab01ab01ab01ab01ab01ab01', now });
  const latest = await readArchitectureReport(db);
  assert.deepEqual(architectureFindings(latest, { now }).map(f => f.code), ['ARCH_FILE_TOO_LARGE', 'ARCH_DUPLICATE_EXPORT', 'ARCH_UNTESTED_MODULES']);
  assert.deepEqual(architectureFindings(latest, { now: now + 9 * 86_400_000 }).map(f => f.code), ['ARCHITECTURE_AUDIT_STALE']);
  assert.deepEqual(architectureFindings(null, { now }), [], 'no report yet is not a finding');
});

test('the weekly workflow posts with GitHub OIDC and the Worker routes it', async () => {
  const workflow = await readFile('.github/workflows/architecture-audit.yml', 'utf8');
  assert.match(workflow, /id-token: write/);
  assert.match(workflow, /\/api\/internal\/architecture-audit/);
  assert.match(workflow, /ARCHITECTURE_REPORT_STORED/);
  assert.match(await readFile('src/professor-live-learning-entry.js', 'utf8'), /maybeHandleArchitectureAuditInternal\(request,env\)/);
  assert.match(await readFile('src/diagnostics/domain-audit.js', 'utf8'), /architectureFindings\(architecture/);
});

test('MEL-AUDIT-06: new Workers AI text models become upgrade discoveries', async () => {
  const { newCatalogModels } = await import('../scripts/workers-ai-catalog-diff.mjs');
  const catalog = { result: [
    { name: '@cf/openai/gpt-oss-120b', task: { name: 'Text Generation' } },
    { name: '@cf/new/coder-2', task: { name: 'Text Generation' } },
    { name: '@cf/old/model', task: { name: 'Text Generation' }, properties: [{ property_id: 'planned_deprecation_date', value: '2026-01-01' }] },
    { name: '@cf/black-forest-labs/flux', task: { name: 'Text-to-Image' } },
  ] };
  assert.deepEqual(newCatalogModels(catalog, ['@cf/openai/gpt-oss-120b']), ['@cf/new/coder-2']);
  const db = sqliteD1();
  const now = Date.now();
  await storeArchitectureReport(db, { schema: 'mel.architecture-audit/v1', new_models: ['@cf/new/coder-2'] }, { sha: 'd'.repeat(40), now });
  assert.deepEqual(architectureFindings(await readArchitectureReport(db), { now }).map(f => f.code), ['UPGRADE_MODEL_AVAILABLE']);
  assert.match(await readFile('.github/workflows/architecture-audit.yml', 'utf8'), /ai\/models\/search/);
});

// MEL-AUDIT-04: exact-SHA identity, recorded once.
test('an exact-SHA report is stored once; an invalid identity or a replay adds no finding', async () => {
  const db = sqliteD1();
  const now = Date.parse('2026-10-26T05:00:00Z');
  const report = { schema: 'mel.architecture-audit/v1', max_lines: 1500, oversized: [{ path: 'src/a.js', lines: 2000 }], untested_modules: [], legacy_imported: [], duplicate_exports: [] };
  await assert.rejects(storeArchitectureReport(db, report, { sha: 'not-a-sha', now }), /IDENTITY_INVALID/);
  assert.equal(await readArchitectureReport(db), null, 'an invalid identity stores nothing');
  const sha = 'c'.repeat(40);
  assert.equal((await storeArchitectureReport(db, report, { sha, now })).status, 'ARCHITECTURE_REPORT_STORED');
  const first = await readArchitectureReport(db);
  const replay = await storeArchitectureReport(db, { ...report, oversized: [...report.oversized, { path: 'src/b.js', lines: 3000 }] }, { sha, now: now + 86_400_000 });
  assert.equal(replay.status, 'ARCHITECTURE_REPORT_ALREADY_STORED');
  const after = await readArchitectureReport(db);
  assert.deepEqual(after, first, 'a replay changes neither the report nor its date');
  assert.deepEqual(architectureFindings(after, { now }).map(f => f.code), ['ARCH_FILE_TOO_LARGE']);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { summarizeUiAudit } from '../scripts/ui-production-audit.mjs';
import { architectureFindings, readArchitectureReport, storeArchitectureReport } from '../src/diagnostics/architecture-audit-store.js';
import { sqliteD1 } from './helpers/sqlite-d1.mjs';

test('UI audit: server errors, JS errors and stuck panels are findings; 401/403 are blocked, not failures', () => {
  const report = summarizeUiAudit([
    { path: '/', panel: null, errors: [], responses: [{ method: 'GET', path: '/api/a', status: 500 }, { method: 'GET', path: '/api/b', status: 401 }], stuck: ['box'] },
    { path: '/professor', panel: 'memory', errors: [], responses: [{ method: 'GET', path: '/api/learning/progress', status: 200 }], stuck: ['memoryOut'] },
    { path: '/professor', panel: 'lora', errors: ['boom'], responses: [{ method: 'GET', path: '/api/c', status: 403 }, { method: 'GET', path: '/api/d', status: 200 }], stuck: [] },
    { path: '/', panel: 'chat', errors: [], responses: [], stuck: ['box'] },
  ]);
  assert.equal(report.api_calls, 5);
  assert.equal(report.blocked_stuck, 2, 'a panel that loaded none of its own data is blocked, not failed');
  assert.equal(report.blocked_calls, 2);
  assert.deepEqual(report.findings.map(f => f.code), ['UI_API_SERVER_ERROR', 'UI_STUCK_LOADING', 'UI_JS_ERROR'], 'the same stuck element on several panels is one finding');
});

test('the UI section rides the weekly report into MEL findings', async () => {
  const db = sqliteD1();
  const now = Date.now();
  await storeArchitectureReport(db, { schema: 'mel.architecture-audit/v1', ui: { schema: 'mel.ui-production-audit/v1', pages: 12, findings: [{ code: 'UI_JS_ERROR', detail: '/professor#lora : boom' }, { code: 'NOT_UI', detail: 'x' }] } }, { sha: 'e'.repeat(40), now });
  assert.deepEqual(architectureFindings(await readArchitectureReport(db), { now }).map(f => f.code), ['UI_JS_ERROR']);
});

test('the production UI audit is read-only and never blocks the weekly report', async () => {
  const script = await readFile('scripts/ui-production-audit.mjs', 'utf8');
  assert.match(script, /if \(route\.request\(\)\.method\(\) === 'GET'\) return route\.continue\(\);/);
  assert.match(script, /return route\.abort\(\);/);
  const workflow = await readFile('.github/workflows/architecture-audit.yml', 'utf8');
  assert.match(workflow, /Audit the production interface \(read-only\)/);
  assert.match(workflow, /add-mask::\$MEL_PARALLEL_PROOF/);
  assert.match(workflow, /UI audit failed to run; report sent without ui/);
});
